import{_ as t}from"./chunks/overview.B8fRd_5s.js";import{_ as a,o,c as r,a2 as n}from"./chunks/framework.DYd_c05j.js";const i="/homelab-console/docs/product-tour/task-evidence.webp",s="/homelab-console/docs/product-tour/approvals.webp",c="/homelab-console/docs/product-tour/audit.webp",w=JSON.parse('{"title":"Product Tour","description":"","frontmatter":{},"headers":[],"relativePath":"product-tour.md","filePath":"product-tour.md","lastUpdated":null}'),d={name:"product-tour.md"};function l(h,e,p,u,m,v){return o(),r("div",null,[...e[0]||(e[0]=[n('<h1 id="product-tour" tabindex="-1">Product Tour <a class="header-anchor" href="#product-tour" aria-label="Permalink to &quot;Product Tour&quot;">​</a></h1><p>Homelab Console turns infrastructure observations into a workflow a human can inspect and control. This tour follows one synthetic DNS incident from detection to evidence, approval, and audit. No live inventory or operator data appears in these screenshots.</p><h2 id="start-in-the-control-room" tabindex="-1">Start in the control room <a class="header-anchor" href="#start-in-the-control-room" aria-label="Permalink to &quot;Start in the control room&quot;">​</a></h2><p><a href="/homelab-console/docs/product-tour/overview.webp"><img src="'+t+'" alt="The Homelab Console overview showing provider health, incidents, tasks, MCP clients, watcher activity, and an operational runbook."></a></p><p>The Overview window brings together provider health, open incidents, the task queue, connected MCP clients, watcher activity, and read-only runbook guidance. It is an operational index rather than a second monitoring system: each card leads to the canonical provider, task, or audit record behind it.</p><h2 id="preserve-evidence-in-a-task" tabindex="-1">Preserve evidence in a task <a class="header-anchor" href="#preserve-evidence-in-a-task" aria-label="Permalink to &quot;Preserve evidence in a task&quot;">​</a></h2><p><a href="/homelab-console/docs/product-tour/task-evidence.webp"><img src="'+i+'" alt="A task investigation showing ownership, lifecycle controls, a summarized finding, and synthetic evidence."></a></p><p>Tasks are the durable handoff boundary between operators and agents. A task can carry ownership, findings, checks, invocation evidence, lifecycle history, and a bounded root-cause context. Agents can hand work to one another without making a chat transcript the source of truth.</p><h2 id="keep-the-human-in-charge-of-writes" tabindex="-1">Keep the human in charge of writes <a class="header-anchor" href="#keep-the-human-in-charge-of-writes" aria-label="Permalink to &quot;Keep the human in charge of writes&quot;">​</a></h2><p><a href="/homelab-console/docs/product-tour/approvals.webp"><img src="'+s+'" alt="The Approvals window showing waiting, consumed, and denied write requests."></a></p><p>Infrastructure writes are not unlocked by connecting an agent. Every write requires a fresh approval for one exact tool invocation and input. The operator can approve or deny it in the console or through Telegram; approvals expire and cannot be replayed.</p><h2 id="inspect-the-complete-audit-trail" tabindex="-1">Inspect the complete audit trail <a class="header-anchor" href="#inspect-the-complete-audit-trail" aria-label="Permalink to &quot;Inspect the complete audit trail&quot;">​</a></h2><p><a href="/homelab-console/docs/product-tour/audit.webp"><img src="'+c+'" alt="The Audit Log showing a successful tool invocation, an approval request, a task finding, and approval decisions."></a></p><p>REST, Telegram, watchers, and MCP clients converge on the same audit model. The log attributes each event to an actor and source, links it to tools and tasks, and stores only normalized, redacted metadata suitable for operational review.</p><h2 id="what-the-tour-demonstrates" tabindex="-1">What the tour demonstrates <a class="header-anchor" href="#what-the-tour-demonstrates" aria-label="Permalink to &quot;What the tour demonstrates&quot;">​</a></h2><ol><li>A watcher reports a bounded observation and opens an incident.</li><li>The incident is represented by a persistent task with explicit ownership.</li><li>Read-only tools collect normalized evidence through the execution core.</li><li>A write request stops at the approval boundary until the operator decides.</li><li>Task, approval, and execution events remain attributable in the audit log.</li></ol><div class="info custom-block"><p class="custom-block-title">SYNTHETIC DATA</p><p>The product-tour dataset is fictional and was rendered through the real web interface. Hostnames, identifiers, timestamps, provider states, and operational events were created exclusively for these screenshots.</p></div><p>Continue with <a href="./architecture">Architecture</a> for the five-plane model or <a href="./security">Security</a> for the trust boundaries behind this workflow.</p>',18)])])}const k=a(d,[["render",l]]);export{w as __pageData,k as default};
